import type * as Path from "effect/Path";
import { toPosixRelativePath } from "../output/posix-relative-path.ts";

/*
The text conventions of every generated file: a reader sees each object and
array one property per line, indented with tabs and trailing commas, and
never a serialized blob. Formatting is a property of the generator, not a
formatter pass over its output.
*/

export type GeneratedSource = {
	readonly filePath: string;
	readonly source: string;
};

export const GENERATED_SOURCE_HEADER =
	"// Code generated by Vorma. DO NOT EDIT.";

/** A tab-indented prefix, matching how a person writes generated source. */
export function toIndent(depth: number): string {
	return "\t".repeat(depth);
}

/** Moves multi-line rendered text deeper by `depth` tabs; the first line keeps its position in the line that embeds it. */
export function indentRenderedText(text: string, depth: number): string {
	return text.split("\n").join(`\n${toIndent(depth)}`);
}

/** The path operations that module-specifier rendering needs; both Effect Path and node:path satisfy it. */
export type SpecifierPathOperations = Pick<
	Path.Path,
	"dirname" | "relative" | "sep"
>;

/** A relative module specifier, explicitly relative even when the target's own name starts with a dot. */
export function getModuleSpecifier(input: {
	readonly path: SpecifierPathOperations;
	readonly fromFilePath: string;
	readonly toFilePath: string;
}): string {
	return toRelativeSpecifier(
		toPosixRelativePath({
			path: input.path,
			from: input.path.dirname(input.fromFilePath),
			to: input.toFilePath,
		}),
	);
}

/** A path is a relative specifier only when it starts with `./` or `../`. */
function toRelativeSpecifier(relativePath: string): string {
	return relativePath.startsWith("./") || relativePath.startsWith("../")
		? relativePath
		: `./${relativePath}`;
}
